use std::collections::HashMap;

use super::extract::{byte_range, is_extracted_item};
use crate::content::{Content, IdentRef, Namespace, Token};
use crate::error::Result;
use crate::ids::{ByteRange, EntityId, RelPath, Slot};
use crate::lang::{BinderClass, Env, Lang, Locator, Resolution, Role, When};

pub fn canonicalize(
    item: tree_sitter::Node<'_>,
    src: &[u8],
    res: &Resolution,
    children: &[(ByteRange, EntityId)],
    lang: &dyn Lang,
) -> Result<Content> {
    let mut tokens = Vec::new();
    let binders = binders_from_res(res);
    let attached = file_attached_nodes(item, lang);
    let item_start = item.start_byte();
    for extra in &attached {
        if extra.start_byte() < item_start {
            walk(
                *extra,
                item,
                src,
                lang,
                children,
                res,
                &binders,
                &mut tokens,
            );
        }
    }
    walk(item, item, src, lang, children, res, &binders, &mut tokens);
    for extra in &attached {
        if extra.start_byte() >= item_start {
            walk(
                *extra,
                item,
                src,
                lang,
                children,
                res,
                &binders,
                &mut tokens,
            );
        }
    }
    Ok(Content { tokens })
}

fn binders_from_res(res: &Resolution) -> HashMap<(u32, u32), (Slot, Namespace)> {
    let mut m = HashMap::new();
    for (r, slot, ns) in &res.slots {
        m.insert((r.start, r.end), (*slot, *ns));
    }
    m
}

pub fn resolve_locals(
    item: tree_sitter::Node<'_>,
    src: &[u8],
    lang: &dyn Lang,
    env: &Env,
) -> Resolution {
    let mut slots = Vec::new();
    let mut binders = Vec::new();
    let mut next: HashMap<Namespace, u32> = HashMap::new();
    inherit_outer_generics(item, src, lang, &mut slots, &mut binders, &mut next);
    collect_binders(
        item,
        src,
        lang,
        None,
        &mut slots,
        &mut binders,
        &mut next,
        item.id(),
    );
    let slot_at: HashMap<(u32, u32), (Slot, Namespace)> = slots
        .iter()
        .map(|(r, s, ns)| ((r.start, r.end), (*s, *ns)))
        .collect();
    let mut refs = Vec::new();
    collect_refs(
        item,
        src,
        lang,
        None,
        &slot_at,
        &binders,
        env,
        &mut refs,
        item.id(),
    );
    // File-tail / inter-item statements are not entities. Resolve them as
    // part of the neighbouring file-root so `rename` rewrites uses there.
    // Walk extras against their own binders: the file-root's name must stay
    // an Entity hole (Local would remain a literal in this item's bytes).
    let mut extra_binders = Vec::new();
    let extra_binder_start = slots.len();
    for extra in file_attached_nodes(item, lang) {
        collect_binders(
            extra,
            src,
            lang,
            None,
            &mut slots,
            &mut extra_binders,
            &mut next,
            extra.id(),
        );
    }
    let extra_slot_at: HashMap<(u32, u32), (Slot, Namespace)> = slots[extra_binder_start..]
        .iter()
        .map(|(r, s, ns)| ((r.start, r.end), (*s, *ns)))
        .collect();
    for extra in file_attached_nodes(item, lang) {
        collect_refs(
            extra,
            src,
            lang,
            None,
            &extra_slot_at,
            &extra_binders,
            env,
            &mut refs,
            extra.id(),
        );
    }
    Resolution { slots, refs }
}

/// Named file-level statements owned by this file-root but not part of its
/// item node: preceding kindless statements (in this entity's bytes, which
/// start where the previous file-root's item ended) and, when this is the
/// last file-root, following tail statements through EOF.
fn file_attached_nodes<'a>(
    item: tree_sitter::Node<'a>,
    lang: &dyn Lang,
) -> Vec<tree_sitter::Node<'a>> {
    if !is_extracted_item(item, lang) || !is_file_root_item(item, lang) {
        return Vec::new();
    }
    let root = syntax_root(item);
    let stmt = top_level_under(item, root);
    let mut children = Vec::new();
    let mut c = root.walk();
    for ch in root.named_children(&mut c) {
        children.push(ch);
    }
    let Some(idx) = children.iter().position(|ch| ch.id() == stmt.id()) else {
        return Vec::new();
    };
    let prev_entity = (0..idx)
        .rev()
        .find(|&i| subtree_has_extracted_entity(children[i], lang));
    let next_entity =
        ((idx + 1)..children.len()).find(|&i| subtree_has_extracted_entity(children[i], lang));
    let start = prev_entity.map(|i| i + 1).unwrap_or(0);
    let last = next_entity.is_none();
    let mut out = Vec::new();
    for (i, ch) in children.into_iter().enumerate() {
        if i == idx {
            continue;
        }
        if i < start {
            continue;
        }
        if i < idx {
            out.push(ch);
            continue;
        }
        if last {
            out.push(ch);
        }
    }
    out
}

fn is_file_root_item(item: tree_sitter::Node<'_>, lang: &dyn Lang) -> bool {
    let mut p = item.parent();
    while let Some(parent) = p {
        if is_extracted_item(parent, lang) {
            return false;
        }
        p = parent.parent();
    }
    true
}

fn syntax_root(item: tree_sitter::Node<'_>) -> tree_sitter::Node<'_> {
    let mut n = item;
    while let Some(p) = n.parent() {
        n = p;
    }
    n
}

fn top_level_under<'a>(
    item: tree_sitter::Node<'a>,
    root: tree_sitter::Node<'a>,
) -> tree_sitter::Node<'a> {
    let mut n = item;
    while let Some(p) = n.parent() {
        if p.id() == root.id() {
            return n;
        }
        n = p;
    }
    item
}

fn subtree_has_extracted_entity(node: tree_sitter::Node<'_>, lang: &dyn Lang) -> bool {
    if is_extracted_item(node, lang) {
        return true;
    }
    let mut c = node.walk();
    for ch in node.named_children(&mut c) {
        if subtree_has_extracted_entity(ch, lang) {
            return true;
        }
    }
    false
}

#[derive(Clone)]
struct BinderInfo {
    range: ByteRange,
    visible_from: u32,
    scope: ByteRange,
    slot: Slot,
    namespace: Namespace,
    class: BinderClass,
    name: String,
}

fn collect_binders<'a>(
    node: tree_sitter::Node<'a>,
    src: &[u8],
    lang: &dyn Lang,
    field: Option<&str>,
    slots: &mut Vec<(ByteRange, Slot, Namespace)>,
    binders: &mut Vec<BinderInfo>,
    next: &mut HashMap<Namespace, u32>,
    root_id: usize,
) {
    if skip_nested_item(node, lang, root_id) {
        return;
    }
    if is_opaque_node(node, lang) && node.id() != root_id {
        return;
    }
    for role in lang.roles(node, field, src, &crate::lang::Env::default()) {
        if let Role::Binder {
            namespace,
            visibility,
            locator,
        } = role
        {
            for name_node in locate(node, locator) {
                for id in ident_leaves(name_node, name_node, src) {
                    let r = byte_range(id);
                    // Typed `|x: T|` is both a `parameter` binder and a child of
                    // `closure_parameters`. One range, one slot.
                    if slots.iter().any(|(existing, _, _)| *existing == r) {
                        continue;
                    }
                    let name = String::from_utf8_lossy(&src[r.start as usize..r.end as usize])
                        .into_owned();
                    // `Ok(x) | Err(x)` is one binding. Fresh slots per occurrence
                    // make O9 rename them apart and rustc reject the or-pattern.
                    let slot =
                        or_pattern_slot(id, &name, namespace, binders).unwrap_or_else(|| {
                            let n = next.entry(namespace).or_insert(0);
                            let slot = Slot(*n);
                            *n += 1;
                            slot
                        });
                    slots.push((r, slot, namespace));
                    let (visible_from, scope) = binder_extent(node, src, lang, root_id, visibility);
                    binders.push(BinderInfo {
                        range: r,
                        visible_from,
                        scope,
                        slot,
                        namespace,
                        class: binder_class(node),
                        name,
                    });
                }
            }
        }
    }
    let mut c = node.walk();
    if c.goto_first_child() {
        loop {
            collect_binders(
                c.node(),
                src,
                lang,
                c.field_name(),
                slots,
                binders,
                next,
                root_id,
            );
            if !c.goto_next_sibling() {
                break;
            }
        }
    }
}

fn collect_refs<'a>(
    node: tree_sitter::Node<'a>,
    src: &[u8],
    lang: &dyn Lang,
    field: Option<&str>,
    slot_at: &HashMap<(u32, u32), (Slot, Namespace)>,
    binders: &[BinderInfo],
    env: &Env,
    refs: &mut Vec<(ByteRange, IdentRef)>,
    root_id: usize,
) {
    if skip_nested_item(node, lang, root_id) {
        return;
    }
    if is_opaque_node(node, lang) && node.id() != root_id {
        return;
    }
    if is_inherent_method_ref(node, src) {
        let r = byte_range(node);
        let name = String::from_utf8_lossy(&src[r.start as usize..r.end as usize]).into_owned();
        if let Some(id) = env.self_methods.get(&name) {
            refs.push((r, IdentRef::Entity(*id)));
        } else if let Some(id) = env
            .nested_items
            .get(&(name.clone(), Namespace::Type))
            .or_else(|| env.nested_items.get(&(name.clone(), Namespace::Value)))
            .copied()
        {
            // Soup `Self::Item` is an identifier, not a type_identifier.
            refs.push((r, IdentRef::Entity(id)));
        } else {
            refs.push((r, IdentRef::Free(name.into())));
        }
        return;
    }
    if is_ident_leaf(node) {
        let r = byte_range(node);
        if slot_at.contains_key(&(r.start, r.end)) {
            // declaration site recorded as slot, not a ref
        } else {
            let name = String::from_utf8_lossy(&src[r.start as usize..r.end as usize]).into_owned();
            let ns = lang
                .roles(node, field, src, &crate::lang::Env::default())
                .into_iter()
                .find_map(|role| match role {
                    Role::Reference { namespace } => Some(namespace),
                    _ => None,
                })
                .unwrap_or(match node.kind() {
                    "type_identifier" | "primitive_type" => Namespace::Type,
                    "lifetime" => Namespace::Lifetime,
                    _ => Namespace::Value,
                });
            let local = binders
                .iter()
                .filter(|b| {
                    b.name == name
                        && b.namespace == ns
                        && b.visible_from <= r.start
                        && b.scope.start <= r.start
                        && r.end <= b.scope.end
                        && !blocked_by_barrier(node, b, ns, src, lang, root_id)
                })
                .max_by_key(|b| (b.scope.start, b.range.start));
            if is_struct_field_key(node)
                || is_dot_field(node)
                || is_type_binding_name(node)
                || is_use_alias(node)
                || in_attribute(node)
            {
                refs.push((r, IdentRef::Free(name.into())));
            } else if let Some(binder) = local
                .filter(|_| !is_rust_nonlocal_ident(node, lang))
                .filter(|b| !const_context_hides_binder(node, b))
            {
                refs.push((r, IdentRef::Local(binder.slot, ns)));
            } else if is_foreign_scoped_ref(node, src, lang, env)
                || is_type_qualified_ref(node, src, lang, env)
            {
                refs.push((r, IdentRef::Free(name.into())));
            } else if env.alias_spellings.contains(&name) && in_scoped_path(node) {
                refs.push((r, IdentRef::Free(name.into())));
            } else if let Some(id) = if let Some(segs) = crate_path_segs(node, src, lang) {
                lookup_use_aware(env, node, ns, &name, |ns| env.lookup_crate_path(&segs, ns))
            } else if let Some((depth, segs)) = super_path_parts(node, src, lang) {
                lookup_use_aware(env, node, ns, &name, |ns| {
                    env.lookup_super_path(depth, &segs, ns)
                })
            } else if let Some(segs) = self_path_segs(node, src, lang) {
                lookup_use_aware(env, node, ns, &name, |ns| env.lookup_self_path(&segs, ns))
            } else if let Some(segs) = aliased_mod_segs(node, src, lang) {
                lookup_use_aware(env, node, ns, &name, |ns| {
                    env.lookup_aliased_mod_path(&segs, ns)
                })
                .or_else(|| env.lookup(&name, ns))
            } else {
                env.lookup(&name, ns).or_else(|| {
                    if under_use_tree(node) && ns != Namespace::Type {
                        env.lookup(&name, Namespace::Type)
                    } else {
                        None
                    }
                })
            } {
                refs.push((r, IdentRef::Entity(id)));
            } else if let Some(ident) = const_generic_arg_ref(
                node,
                &name,
                r,
                binders,
                env,
                src,
                lang,
                root_id,
            ) {
                refs.push((r, ident));
            } else {
                refs.push((r, IdentRef::Free(name.into())));
            }
        }
        return;
    }
    let mut c = node.walk();
    if c.goto_first_child() {
        loop {
            collect_refs(
                c.node(),
                src,
                lang,
                c.field_name(),
                slot_at,
                binders,
                env,
                refs,
                root_id,
            );
            if !c.goto_next_sibling() {
                break;
            }
        }
    }
}

fn locate<'a>(node: tree_sitter::Node<'a>, loc: Locator) -> Vec<tree_sitter::Node<'a>> {
    match loc {
        Locator::Itself => vec![node],
        Locator::Field(f) => node.child_by_field_name(f).into_iter().collect(),
        Locator::ChildIndex(i) => node.named_child(i as u32).into_iter().collect(),
        Locator::FieldWithKind(f, k) => node
            .child_by_field_name(f)
            .filter(|n| n.kind() == k)
            .into_iter()
            .collect(),
    }
}

fn ident_leaves<'a>(
    node: tree_sitter::Node<'a>,
    pattern_root: tree_sitter::Node<'a>,
    src: &[u8],
) -> Vec<tree_sitter::Node<'a>> {
    if is_ident_leaf(node) {
        let t = node.kind();
        if t == "_" || node_is_wildcard(node) {
            return vec![];
        }
        return (!is_pattern_constructor(node, pattern_root, src))
            .then_some(node)
            .into_iter()
            .collect();
    }
    if node.kind() == "match_pattern" {
        let mut out = Vec::new();
        let mut c = node.walk();
        if c.goto_first_child() {
            loop {
                if c.field_name() != Some("condition") {
                    out.extend(ident_leaves(c.node(), pattern_root, src));
                }
                if !c.goto_next_sibling() {
                    break;
                }
            }
        }
        return out;
    }
    let mut out = Vec::new();
    let mut c = node.walk();
    for ch in node.named_children(&mut c) {
        out.extend(ident_leaves(ch, pattern_root, src));
    }
    out
}

fn binder_extent(
    node: tree_sitter::Node<'_>,
    src: &[u8],
    lang: &dyn Lang,
    root_id: usize,
    visibility: crate::lang::Visibility,
) -> (u32, ByteRange) {
    match visibility {
        crate::lang::Visibility::AfterStmt => {
            let visible_from = node.end_byte() as u32;
            if node.kind() == "let_condition" {
                if let Some(parent) = node.parent() {
                    let end = match parent.kind() {
                        "if_expression" => parent
                            .child_by_field_name("consequence")
                            .map(|c| c.end_byte() as u32),
                        "while_expression" => {
                            parent.child_by_field_name("body").map(|c| c.end_byte() as u32)
                        }
                        _ => None,
                    };
                    if let Some(end) = end {
                        return (
                            visible_from,
                            ByteRange {
                                start: visible_from,
                                end,
                            },
                        );
                    }
                }
            }
            (visible_from, enclosing_scope(node, src, lang, root_id))
        }
        crate::lang::Visibility::Hoisted => {
            let scope = enclosing_var_scope(node, src, lang, root_id);
            (scope.start, scope)
        }
        crate::lang::Visibility::Sub(fields) => {
            let scope = sub_field_scope(node, fields)
                .unwrap_or_else(|| enclosing_scope(node, src, lang, root_id));
            (scope.start, scope)
        }
        crate::lang::Visibility::Whole => {
            if node.kind() == "label" {
                if let Some(parent) = node.parent() {
                    if parent.kind() == "for_expression" {
                        if let Some(body) = parent.child_by_field_name("body") {
                            let scope = byte_range(body);
                            return (scope.start, scope);
                        }
                    }
                }
            }
            let scope = enclosing_scope(node, src, lang, root_id);
            (scope.start, scope)
        }
    }
}

fn enclosing_var_scope(
    node: tree_sitter::Node<'_>,
    src: &[u8],
    lang: &dyn Lang,
    root_id: usize,
) -> ByteRange {
    if lang.name() != "javascript" {
        return enclosing_scope(node, src, lang, root_id);
    }
    let mut current = node.parent();
    while let Some(parent) = current {
        if is_js_var_scope(parent.kind()) {
            return byte_range(parent);
        }
        if parent.id() == root_id {
            break;
        }
        current = parent.parent();
    }
    enclosing_scope(node, src, lang, root_id)
}

fn is_js_var_scope(kind: &str) -> bool {
    matches!(
        kind,
        "program"
            | "function_declaration"
            | "generator_function_declaration"
            | "function_expression"
            | "generator_function"
            | "method_definition"
            | "arrow_function"
            | "class_static_block"
    )
}

fn sub_field_scope(node: tree_sitter::Node<'_>, fields: &[&str]) -> Option<ByteRange> {
    let mut current = Some(node);
    while let Some(n) = current {
        let mut start = u32::MAX;
        let mut end = 0u32;
        let mut found = false;
        for field in fields {
            if let Some(child) = n.child_by_field_name(field) {
                let r = byte_range(child);
                start = start.min(r.start);
                end = end.max(r.end);
                found = true;
            }
        }
        if found {
            return Some(ByteRange { start, end });
        }
        current = n.parent();
    }
    None
}

fn enclosing_scope(
    node: tree_sitter::Node<'_>,
    src: &[u8],
    lang: &dyn Lang,
    root_id: usize,
) -> ByteRange {
    let mut current = node.parent();
    while let Some(parent) = current {
        if lang
            .roles(parent, None, src, &crate::lang::Env::default())
            .iter()
            .any(|role| matches!(role, Role::Scope { .. }))
        {
            return byte_range(parent);
        }
        if parent.id() == root_id {
            break;
        }
        current = parent.parent();
    }
    let mut root = node;
    while root.id() != root_id {
        root = root.parent().expect("resolver node belongs to root");
    }
    byte_range(root)
}

fn blocked_by_barrier(
    from: tree_sitter::Node<'_>,
    binder: &BinderInfo,
    ns: Namespace,
    src: &[u8],
    lang: &dyn Lang,
    root_id: usize,
) -> bool {
    let mut current = from.parent();
    while let Some(parent) = current {
        for role in lang.roles(parent, None, src, &crate::lang::Env::default()) {
            if let Role::Scope { barriers, .. } = role {
                let blocks = barriers.iter().any(|b| {
                    b.ns == ns && b.when == When::Always && b.class == binder.class
                });
                if blocks {
                    let scope = byte_range(parent);
                    let inside = scope.start <= binder.range.start && binder.range.end <= scope.end;
                    if !inside {
                        return true;
                    }
                }
            }
        }
        if parent.id() == root_id {
            break;
        }
        current = parent.parent();
    }
    false
}

/// Nested entities are skipped, so `When::ThroughBlock` cannot be applied by
/// walking into them. Copy ancestor `type_parameters` onto this item only when
/// the path does not go through a `block` (impl/trait methods inherit `T`;
/// a nested `fn` inside `fn f<T>` does not).
fn inherit_outer_generics(
    item: tree_sitter::Node<'_>,
    src: &[u8],
    lang: &dyn Lang,
    slots: &mut Vec<(ByteRange, Slot, Namespace)>,
    binders: &mut Vec<BinderInfo>,
    next: &mut HashMap<Namespace, u32>,
) {
    let scope = byte_range(item);
    let mut ancestor = item.parent();
    while let Some(node) = ancestor {
        if let Some(tp) = node.child_by_field_name("type_parameters") {
            if !crosses_block(node, item) {
                add_generic_binders(tp, src, lang, scope, slots, binders, next);
            }
        }
        ancestor = node.parent();
    }
}

fn crosses_block(ancestor: tree_sitter::Node<'_>, item: tree_sitter::Node<'_>) -> bool {
    let mut current = item.parent();
    while let Some(node) = current {
        if node.id() == ancestor.id() {
            return false;
        }
        if node.kind() == "block" {
            return true;
        }
        current = node.parent();
    }
    false
}

fn add_generic_binders(
    node: tree_sitter::Node<'_>,
    src: &[u8],
    lang: &dyn Lang,
    scope: ByteRange,
    slots: &mut Vec<(ByteRange, Slot, Namespace)>,
    binders: &mut Vec<BinderInfo>,
    next: &mut HashMap<Namespace, u32>,
) {
    if matches!(
        node.kind(),
        "type_parameter" | "lifetime_parameter" | "const_parameter"
    ) {
        for role in lang.roles(node, None, src, &Env::default()) {
            if let Role::Binder {
                namespace, locator, ..
            } = role
            {
                for name_node in locate(node, locator) {
                    for id in ident_leaves(name_node, name_node, src) {
                        let r = byte_range(id);
                        let n = next.entry(namespace).or_insert(0);
                        let slot = Slot(*n);
                        *n += 1;
                        slots.push((r, slot, namespace));
                        binders.push(BinderInfo {
                            range: r,
                            visible_from: scope.start,
                            scope,
                            slot,
                            namespace,
                            class: BinderClass::Generic,
                            name: String::from_utf8_lossy(&src[r.start as usize..r.end as usize])
                                .into_owned(),
                        });
                    }
                }
            }
        }
    }
    let mut c = node.walk();
    if c.goto_first_child() {
        loop {
            add_generic_binders(c.node(), src, lang, scope, slots, binders, next);
            if !c.goto_next_sibling() {
                break;
            }
        }
    }
}

fn is_pattern_constructor(
    node: tree_sitter::Node<'_>,
    pattern_root: tree_sitter::Node<'_>,
    src: &[u8],
) -> bool {
    let mut current = node;
    while current.id() != pattern_root.id() {
        let Some(parent) = current.parent() else {
            break;
        };
        match parent.kind() {
            "tuple_struct_pattern" | "struct_pattern" => {
                if parent.child_by_field_name("type").is_some_and(|n| {
                    n.start_byte() <= node.start_byte() && node.end_byte() <= n.end_byte()
                }) {
                    return true;
                }
            }
            "scoped_identifier" | "scoped_type_identifier" | "generic_pattern" => {
                return true;
            }
            "field_pattern" => {
                if node.kind() != "shorthand_field_identifier"
                    && parent.child_by_field_name("name").is_some_and(|n| {
                        n.start_byte() <= node.start_byte() && node.end_byte() <= n.end_byte()
                    })
                {
                    return true;
                }
            }
            "captured_pattern" => {
                if parent.named_child(0).is_some_and(|n| n.id() == node.id()) {
                    return false;
                }
            }
            _ => {}
        }
        current = parent;
    }
    // Unit variants / consts (`None`, `AfterStmt`) are identifier patterns.
    // Bindings in this crate are snake_case; PascalCase is the constructor.
    // A const-generic `N` is an identifier but not a pattern.
    if node.kind() == "identifier"
        && !node
            .parent()
            .is_some_and(|p| p.kind() == "const_parameter")
    {
        let name = &src[node.start_byte()..node.end_byte()];
        if name.first().is_some_and(|b| b.is_ascii_uppercase()) {
            return true;
        }
    }
    false
}

fn or_pattern_slot(
    ident: tree_sitter::Node<'_>,
    name: &str,
    ns: Namespace,
    binders: &[BinderInfo],
) -> Option<Slot> {
    let mut current = ident.parent();
    while let Some(parent) = current {
        if parent.kind() == "or_pattern" {
            let start = parent.start_byte() as u32;
            let end = parent.end_byte() as u32;
            if let Some(b) = binders.iter().rev().find(|b| {
                b.namespace == ns && b.name == name && start <= b.range.start && b.range.end <= end
            }) {
                return Some(b.slot);
            }
        }
        current = parent.parent();
    }
    None
}

fn is_struct_field_key(node: tree_sitter::Node<'_>) -> bool {
    let Some(parent) = node.parent() else {
        return false;
    };
    match parent.kind() {
        "field_initializer" => parent.child_by_field_name("field").is_some_and(|f| {
            f.id() == node.id()
                || (f.start_byte() <= node.start_byte() && node.end_byte() <= f.end_byte())
        }),
        // `S { id: x }`: `id` names the field (SPEC §9, no namespace), not a
        // local or `fn id`. Shorthand `S { id }` is a binder, not a key.
        "field_pattern" => {
            node.kind() != "shorthand_field_identifier"
                && parent.child_by_field_name("name").is_some_and(|n| {
                    n.id() == node.id()
                        || (n.start_byte() <= node.start_byte() && node.end_byte() <= n.end_byte())
                })
        }
        _ => false,
    }
}

/// `use crate::a::h as hh`: `hh` is the local alias, not the imported
/// entity's name. Rename of `h` must not rewrite the alias.
fn is_use_alias(node: tree_sitter::Node<'_>) -> bool {
    let Some(parent) = node.parent() else {
        return false;
    };
    if parent.kind() != "use_as_clause" {
        return false;
    }
    parent.child_by_field_name("alias").is_some_and(|n| {
        n.id() == node.id()
            || (n.start_byte() <= node.start_byte() && node.end_byte() <= n.end_byte())
    })
}

/// `foo` in `foo::parse` / `crate::foo::parse` is a path segment. A module alias
/// spelling stays Free there. A bare `foo()` is not a path and may be a local fn.
fn in_scoped_path(node: tree_sitter::Node<'_>) -> bool {
    node.parent().is_some_and(|p| {
        matches!(
            p.kind(),
            "scoped_identifier"
                | "scoped_type_identifier"
                | "scoped_use_list"
                | "use_as_clause"
                | "use_wildcard"
        )
    })
}

/// `#[parse]` is an attribute / derive / lint name, not the value-namespace
/// `fn parse`. A later proc-macro identity can bind Macro; until then Free.
fn in_attribute(mut node: tree_sitter::Node<'_>) -> bool {
    loop {
        let Some(parent) = node.parent() else {
            return false;
        };
        if matches!(
            parent.kind(),
            "attribute_item" | "inner_attribute_item" | "attribute"
        ) {
            return true;
        }
        node = parent;
    }
}

/// `It<Item = T>`: the left `Item` is an associated-type binding name, not a
/// reference to a type `Item` in scope (SPEC §9; needs the receiver's type).
fn is_type_binding_name(node: tree_sitter::Node<'_>) -> bool {
    let Some(parent) = node.parent() else {
        return false;
    };
    if parent.kind() != "type_binding" {
        return false;
    }
    parent.child_by_field_name("name").is_some_and(|n| {
        n.id() == node.id()
            || (n.start_byte() <= node.start_byte() && node.end_byte() <= n.end_byte())
    })
}

/// `.src` is a field or method name, including inside `vec![self.src.len()]`
/// where the path is a flat `token_tree`. A same-named local must not win.
fn is_dot_field(node: tree_sitter::Node<'_>) -> bool {
    let mut prev = node.prev_sibling();
    while let Some(n) = prev {
        if n.kind() == "." {
            return true;
        }
        if n.is_named() {
            return false;
        }
        prev = n.prev_sibling();
    }
    false
}

fn is_rust_nonlocal_ident(node: tree_sitter::Node<'_>, lang: &dyn Lang) -> bool {
    if lang.name() != "rust" {
        return false;
    }
    let mut current = node;
    while let Some(parent) = current.parent() {
        if matches!(
            parent.kind(),
            "scoped_identifier" | "scoped_type_identifier"
        ) {
            return true;
        }
        if matches!(
            parent.kind(),
            "block" | "function_item" | "function_signature_item"
        ) {
            break;
        }
        current = parent;
    }
    false
}

/// `RedbStore::open` is not a free `fn open`. Type-relative names stay Free
/// (SPEC §9) unless they are same-impl inherent methods (earlier) or the
/// qualifier is `Self` / the enclosing impl or trait (`S::Item` / `T::Item` /
/// `Tr::Item` in `impl Tr for S` is the associated type, not a free `Item`).
fn is_type_qualified_ref(
    node: tree_sitter::Node<'_>,
    src: &[u8],
    lang: &dyn Lang,
    env: &Env,
) -> bool {
    if lang.name() != "rust" {
        return false;
    }
    if under_use_tree(node) {
        return false;
    }
    if let Some(root) = scoped_path_root(node) {
        let root_name =
            std::str::from_utf8(&src[root.start_byte()..root.end_byte()]).unwrap_or("");
        if matches!(root_name, "crate" | "super" | "self") {
            return false;
        }
    }
    let Some(parent) = node.parent() else {
        return false;
    };
    if !matches!(
        parent.kind(),
        "scoped_identifier" | "scoped_type_identifier"
    ) {
        return false;
    }
    if parent.child_by_field_name("name").map(|n| n.id()) != Some(node.id()) {
        return false;
    }
    let Some(path) = parent.child_by_field_name("path") else {
        return false;
    };
    let Some(qual) = scoped_qualifier(path) else {
        return false;
    };
    let name = std::str::from_utf8(&src[qual.start_byte()..qual.end_byte()]).unwrap_or("");
    if matches!(name, "crate" | "super" | "self" | "Self") {
        return false;
    }
    if Some(name.as_bytes()) == enclosing_impl_type_name(node, src)
        || Some(name.as_bytes()) == enclosing_impl_trait_name(node, src)
    {
        return false;
    }
    if env
        .lookup(name, Namespace::Type)
        .is_some_and(|id| env.is_mod(id))
    {
        return false;
    }
    env.lookup_global(name, Namespace::Type).is_some()
}

fn scoped_qualifier(mut node: tree_sitter::Node<'_>) -> Option<tree_sitter::Node<'_>> {
    loop {
        match node.kind() {
            "scoped_identifier" | "scoped_type_identifier" => {
                node = node.child_by_field_name("name")?;
            }
            "generic_type" => {
                node = node.child_by_field_name("type")?;
            }
            "bracketed_type" => {
                node = node.named_child(0)?;
            }
            "qualified_type" => {
                node = node.child_by_field_name("type")?;
            }
            _ => return Some(node),
        }
    }
}

fn under_use_tree(mut node: tree_sitter::Node<'_>) -> bool {
    while let Some(parent) = node.parent() {
        if matches!(
            parent.kind(),
            "use_declaration" | "use_as_clause" | "use_list" | "use_wildcard"
        ) {
            return true;
        }
        node = parent;
    }
    false
}

/// Identifiers in a `use` tree are Value nodes. Type-only names (type aliases,
/// traits, unions) still have to bind, so a miss retries Type and then the
/// unique last-segment module map.
fn lookup_use_aware(
    env: &Env,
    node: tree_sitter::Node<'_>,
    ns: Namespace,
    name: &str,
    path: impl Fn(Namespace) -> Option<EntityId>,
) -> Option<EntityId> {
    path(ns)
        .or_else(|| {
            if under_use_tree(node) && ns != Namespace::Type {
                path(Namespace::Type)
            } else {
                None
            }
        })
        .or_else(|| {
            if under_use_tree(node) {
                env.lookup_module(name, ns).or_else(|| {
                    if ns != Namespace::Type {
                        env.lookup_module(name, Namespace::Type)
                    } else {
                        None
                    }
                })
            } else {
                None
            }
        })
}

/// `axum::response` is not our `fn response` in another file. If the leftmost
/// path segment is not `crate`/`super`/`self` and is not an entity, every
/// later segment is Free. `use crate::a::f` must not look foreign: wrapping
/// `use` nodes are not the path root.
fn is_foreign_scoped_ref(
    node: tree_sitter::Node<'_>,
    src: &[u8],
    lang: &dyn Lang,
    env: &Env,
) -> bool {
    if lang.name() != "rust" {
        return false;
    }
    let Some(root) = scoped_path_root(node) else {
        return false;
    };
    if root.id() == node.id() {
        return false;
    }
    let name = std::str::from_utf8(&src[root.start_byte()..root.end_byte()]).unwrap_or("");
    if matches!(name, "crate" | "super" | "self" | "Self") {
        return false;
    }
    if env.lookup(name, Namespace::Type).is_some() || env.lookup(name, Namespace::Value).is_some() {
        return false;
    }
    if env.alias_spellings.contains(name) {
        return false;
    }
    if env
        .lookup_crate_path(&[name.to_string()], Namespace::Type)
        .is_some()
    {
        return false;
    }
    env.lookup_global(name, Namespace::Value).is_none()
        && env.lookup_global(name, Namespace::Type).is_none()
}

fn aliased_mod_segs(
    node: tree_sitter::Node<'_>,
    src: &[u8],
    lang: &dyn Lang,
) -> Option<Vec<String>> {
    if lang.name() != "rust" {
        return None;
    }
    let segs = scoped_path_idents(node, src)?;
    if segs.len() < 2 {
        return None;
    }
    if matches!(segs[0].as_str(), "crate" | "super" | "self" | "Self") {
        return None;
    }
    Some(segs)
}

fn is_crate_path(node: tree_sitter::Node<'_>, src: &[u8], lang: &dyn Lang) -> bool {
    path_root_is(node, src, lang, "crate")
}

fn crate_path_segs(node: tree_sitter::Node<'_>, src: &[u8], lang: &dyn Lang) -> Option<Vec<String>> {
    if !is_crate_path(node, src, lang) {
        return None;
    }
    let mut segs = scoped_path_idents(node, src)?;
    if segs.first().map(String::as_str) != Some("crate") {
        return None;
    }
    segs.remove(0);
    Some(segs)
}

fn super_path_parts(
    node: tree_sitter::Node<'_>,
    src: &[u8],
    lang: &dyn Lang,
) -> Option<(usize, Vec<String>)> {
    if lang.name() != "rust" {
        return None;
    }
    let segs = scoped_path_idents(node, src)?;
    let depth = segs.iter().take_while(|s| s.as_str() == "super").count();
    if depth == 0 {
        return None;
    }
    Some((depth, segs[depth..].to_vec()))
}

fn self_path_segs(node: tree_sitter::Node<'_>, src: &[u8], lang: &dyn Lang) -> Option<Vec<String>> {
    if lang.name() != "rust" {
        return None;
    }
    let mut segs = scoped_path_idents(node, src)?;
    if segs.first().map(String::as_str) != Some("self") {
        return None;
    }
    segs.remove(0);
    Some(segs)
}

fn scoped_path_idents(node: tree_sitter::Node<'_>, src: &[u8]) -> Option<Vec<String>> {
    let parent = node.parent()?;
    if !matches!(parent.kind(), "scoped_identifier" | "scoped_type_identifier") {
        return None;
    }
    let path = parent.child_by_field_name("path")?;
    let mut segs = path_idents(path, src);
    segs.push(node_text(node, src));
    Some(segs)
}

fn path_idents(node: tree_sitter::Node<'_>, src: &[u8]) -> Vec<String> {
    match node.kind() {
        "scoped_identifier" | "scoped_type_identifier" => {
            let mut segs = node
                .child_by_field_name("path")
                .map(|p| path_idents(p, src))
                .unwrap_or_default();
            if let Some(name) = node.child_by_field_name("name") {
                segs.push(node_text(name, src));
            }
            segs
        }
        "bracketed_type" => node
            .named_child(0)
            .map(|n| path_idents(n, src))
            .unwrap_or_default(),
        "qualified_type" => node
            .child_by_field_name("type")
            .map(|n| path_idents(n, src))
            .unwrap_or_default(),
        "generic_type" => node
            .child_by_field_name("type")
            .map(|n| path_idents(n, src))
            .unwrap_or_default(),
        _ => vec![node_text(node, src)],
    }
}

fn node_text(node: tree_sitter::Node<'_>, src: &[u8]) -> String {
    std::str::from_utf8(&src[node.start_byte()..node.end_byte()])
        .unwrap_or("")
        .to_string()
}

/// `use` names in the same module as `item`. Nested inline mods keep their
/// own imports; they do not inherit the outer file's.
pub(crate) fn fill_use_imports(
    env: &mut Env,
    item: tree_sitter::Node<'_>,
    src: &[u8],
    lang: &dyn Lang,
) {
    env.use_imports.clear();
    env.use_aliases.clear();
    if lang.name() != "rust" {
        return;
    }
    collect_use_imports(env, use_scope_node(item), src);
    collect_nested_use_imports(env, item, src);
}

pub(crate) fn collect_nested_use_imports(env: &mut Env, item: tree_sitter::Node<'_>, src: &[u8]) {
    walk_nested_uses(env, item, src, item.id());
}

fn walk_nested_uses(
    env: &mut Env,
    node: tree_sitter::Node<'_>,
    src: &[u8],
    item_id: usize,
) {
    if node.id() != item_id && is_nested_use_barrier(node.kind()) {
        return;
    }
    if node.kind() == "use_declaration" {
        bind_use_declaration(env, node, src);
        return;
    }
    let mut c = node.walk();
    if c.goto_first_child() {
        loop {
            walk_nested_uses(env, c.node(), src, item_id);
            if !c.goto_next_sibling() {
                break;
            }
        }
    }
}

fn is_nested_use_barrier(kind: &str) -> bool {
    matches!(
        kind,
        "function_item"
            | "function_signature_item"
            | "mod_item"
            | "impl_item"
            | "trait_item"
            | "struct_item"
            | "enum_item"
            | "union_item"
            | "const_item"
            | "static_item"
            | "type_item"
            | "macro_definition"
            | "extern_crate_declaration"
    )
}

fn use_scope_node(mut node: tree_sitter::Node<'_>) -> tree_sitter::Node<'_> {
    loop {
        let Some(parent) = node.parent() else {
            return node;
        };
        if node.kind() == "declaration_list" && parent.kind() == "mod_item" {
            return node;
        }
        if parent.kind() == "source_file" {
            return parent;
        }
        node = parent;
    }
}

pub(crate) fn collect_use_imports(env: &mut Env, root: tree_sitter::Node<'_>, src: &[u8]) {
    let mut c = root.walk();
    if !c.goto_first_child() {
        return;
    }
    loop {
        let n = c.node();
        if n.kind() == "use_declaration" {
            bind_use_declaration(env, n, src);
        }
        if !c.goto_next_sibling() {
            break;
        }
    }
}

fn bind_use_declaration(env: &mut Env, n: tree_sitter::Node<'_>, src: &[u8]) {
    if env.bind_reexports && !use_is_pub(n, src) {
        return;
    }
    if let Some(arg) = n.child_by_field_name("argument") {
        import_use_tree(env, arg, src, &[]);
        return;
    }
    for i in 0..n.named_child_count() {
        let Some(ch) = n.named_child(i as u32) else {
            continue;
        };
        if ch.kind() == "visibility_modifier" {
            continue;
        }
        import_use_tree(env, ch, src, &[]);
        break;
    }
}

fn use_is_pub(node: tree_sitter::Node<'_>, src: &[u8]) -> bool {
    if let Some(v) = node.child_by_field_name("visibility") {
        return node_text(v, src).contains("pub");
    }
    for i in 0..node.named_child_count() {
        if let Some(ch) = node.named_child(i as u32) {
            if ch.kind() == "visibility_modifier" {
                return node_text(ch, src).contains("pub");
            }
        }
    }
    false
}

fn import_use_tree(env: &mut Env, node: tree_sitter::Node<'_>, src: &[u8], prefix: &[String]) {
    match node.kind() {
        "use_as_clause" => {
            let Some(path) = node.child_by_field_name("path") else {
                return;
            };
            let mut segs = prefix.to_vec();
            segs.extend(path_idents(path, src));
            let name = node
                .child_by_field_name("alias")
                .map(|a| node_text(a, src))
                .or_else(|| segs.last().cloned())
                .unwrap_or_default();
            bind_use(env, &segs, &name);
        }
        "use_list" => {
            for i in 0..node.named_child_count() {
                if let Some(ch) = node.named_child(i as u32) {
                    import_use_tree(env, ch, src, prefix);
                }
            }
        }
        "scoped_use_list" => {
            let mut segs = prefix.to_vec();
            if let Some(p) = node.child_by_field_name("path") {
                segs.extend(path_idents(p, src));
            }
            if let Some(list) = node.child_by_field_name("list") {
                import_use_tree(env, list, src, &segs);
                return;
            }
            for i in 0..node.named_child_count() {
                if let Some(ch) = node.named_child(i as u32) {
                    if ch.kind() == "use_list" {
                        import_use_tree(env, ch, src, &segs);
                    }
                }
            }
        }
        "use_wildcard" => {
            let mut segs = prefix.to_vec();
            for i in 0..node.named_child_count() {
                if let Some(ch) = node.named_child(i as u32) {
                    if ch.kind() == "*" || node_text(ch, src) == "*" {
                        continue;
                    }
                    segs.extend(path_idents(ch, src));
                }
            }
            bind_glob(env, &segs);
        }
        _ => {
            let mut segs = prefix.to_vec();
            segs.extend(path_idents(node, src));
            if segs.last().map(|s| s.as_str()) == Some("self") && segs.len() >= 2 {
                let alias = segs[segs.len() - 2].clone();
                bind_use(env, &segs[..segs.len() - 1], &alias);
                return;
            }
            let Some(name) = segs.last().cloned() else {
                return;
            };
            if name == "*" {
                bind_glob(env, &segs[..segs.len() - 1]);
                return;
            }
            bind_use(env, &segs, &name);
        }
    }
}

fn bind_glob(env: &mut Env, prefix: &[String]) {
    let Some(map) = glob_names(env, prefix) else {
        return;
    };
    for (k, id) in map {
        if env.bind_reexports {
            insert_reexport(env, k.0, k.1, id);
        } else {
            insert_file_import(env, k.0.clone(), k.1, id);
            insert_mod_import(env, k.0.clone(), k.1, id);
            env.use_imports.insert(k, id);
        }
    }
}

fn insert_reexport(env: &mut Env, name: String, ns: Namespace, id: EntityId) {
    if let Some(file) = env.current_file.clone() {
        env.file_reexports
            .entry(file)
            .or_default()
            .insert((name.clone(), ns), id);
    }
    insert_file_import(env, name.clone(), ns, id);
    if let Some(m) = env.self_mod {
        env.mod_reexports
            .entry(m)
            .or_default()
            .insert((name, ns), id);
    }
}

fn insert_file_import(env: &mut Env, name: String, ns: Namespace, id: EntityId) {
    if env.in_nested_mod {
        return;
    }
    if let Some(file) = env.current_file.clone() {
        env.file_imports
            .entry(file)
            .or_default()
            .insert((name, ns), id);
    }
}

fn insert_mod_import(env: &mut Env, name: String, ns: Namespace, id: EntityId) {
    if let Some(m) = env.self_mod {
        env.mod_imports
            .entry(m)
            .or_default()
            .insert((name, ns), id);
    }
}

fn glob_names(
    env: &Env,
    prefix: &[String],
) -> Option<HashMap<(String, Namespace), EntityId>> {
    if prefix.is_empty() {
        return None;
    }
    if prefix.len() == 1 && prefix[0] == "super" {
        return super_glob_map(env);
    }
    if prefix[0] == "crate" {
        if prefix.len() == 1 {
            return crate_root_glob(env);
        }
        let m = env.lookup_crate_path(&prefix[1..], Namespace::Type)?;
        return glob_mod(env, m);
    }
    if prefix[0] == "self" {
        if prefix.len() == 1 {
            return env
                .self_mod
                .and_then(|m| glob_mod(env, m))
                .or_else(|| {
                    env.current_file
                        .as_ref()
                        .and_then(|f| merge_file_glob(env, f))
                });
        }
        let m = env.lookup_self_path(&prefix[1..], Namespace::Type)?;
        return glob_mod(env, m);
    }
    if prefix[0] == "super" {
        let depth = prefix.iter().take_while(|s| s.as_str() == "super").count();
        let rest = &prefix[depth..];
        if rest.is_empty() {
            return super_glob_at(env, depth);
        }
        let m = env.lookup_super_path(depth, rest, Namespace::Type)?;
        return glob_mod(env, m);
    }
    let m = env
        .lookup_self_path(prefix, Namespace::Type)
        .or_else(|| env.lookup_crate_path(prefix, Namespace::Type))?;
    glob_mod(env, m)
}

fn glob_mod(
    env: &Env,
    m: EntityId,
) -> Option<HashMap<(String, Namespace), EntityId>> {
    let mut map = env.mod_items.get(&m).cloned().unwrap_or_default();
    if let Some(re) = env.mod_reexports.get(&m) {
        map.extend(re.clone());
    }
    if let Some(im) = env.mod_imports.get(&m) {
        map.extend(im.clone());
    }
    if map.is_empty() {
        None
    } else {
        Some(map)
    }
}

fn crate_root_glob(env: &Env) -> Option<HashMap<(String, Namespace), EntityId>> {
    let file = env.super_files.last().or(env.current_file.as_ref())?;
    merge_file_glob(env, file)
}

fn merge_file_glob(
    env: &Env,
    file: &RelPath,
) -> Option<HashMap<(String, Namespace), EntityId>> {
    let mut map = env.by_file.get(file).cloned().unwrap_or_default();
    if let Some(re) = env.file_reexports.get(file) {
        map.extend(re.clone());
    }
    if let Some(im) = env.file_imports.get(file) {
        map.extend(im.clone());
    }
    if map.is_empty() {
        None
    } else {
        Some(map)
    }
}

fn super_glob_map(env: &Env) -> Option<HashMap<(String, Namespace), EntityId>> {
    super_glob_at(env, 1)
}

fn super_glob_at(env: &Env, depth: usize) -> Option<HashMap<(String, Namespace), EntityId>> {
    if depth == 0 {
        return None;
    }
    let i = depth - 1;
    if let Some(map) = env.super_stack.get(i) {
        return Some(map.clone());
    }
    let rest = i - env.super_stack.len();
    if env.inline_mod && rest == 0 {
        let file = env.current_file.as_ref()?;
        return merge_file_glob(env, file);
    }
    let file_i = if env.inline_mod { rest - 1 } else { rest };
    let file = env.super_files.get(file_i)?;
    let mut map = merge_file_glob(env, file).unwrap_or_default();
    if env.include_splices.contains(file) {
        if let Some(&m) = env.file_of_mod.get(file) {
            if let Some(more) = glob_mod(env, m) {
                map.extend(more);
            }
        }
    }
    if map.is_empty() {
        None
    } else {
        Some(map)
    }
}

fn bind_use(env: &mut Env, segs: &[String], alias: &str) {
    if alias.is_empty() || segs.is_empty() {
        return;
    }
    let imported = segs
        .iter()
        .rev()
        .find(|s| !matches!(s.as_str(), "self" | "super" | "crate"))
        .map(|s| s.as_str())
        .unwrap_or("");
    let aliased = !imported.is_empty() && alias != imported;
    if aliased {
        env.alias_spellings.insert(alias.to_string());
    }
    for ns in [Namespace::Value, Namespace::Type] {
        let Some(id) = resolve_use_path(env, segs, ns) else {
            if env.bind_reexports {
                continue;
            }
            if aliased {
                env.use_aliases.insert(alias.to_string());
            }
            continue;
        };
        if env.bind_reexports {
            if !aliased || env.is_mod(id) {
                insert_reexport(env, alias.to_string(), ns, id);
            }
            continue;
        }
        if aliased && !env.is_mod(id) {
            env.use_aliases.insert(alias.to_string());
            continue;
        }
        insert_file_import(env, alias.to_string(), ns, id);
        insert_mod_import(env, alias.to_string(), ns, id);
        env.use_imports.insert((alias.to_string(), ns), id);
    }
}

fn resolve_use_path(env: &Env, segs: &[String], ns: Namespace) -> Option<EntityId> {
    if segs.is_empty() {
        return None;
    }
    let segs = if segs.last().map(|s| s.as_str()) == Some("self") && segs.len() >= 2 {
        &segs[..segs.len() - 1]
    } else {
        segs
    };
    match segs[0].as_str() {
        "crate" => env.lookup_crate_path(&segs[1..], ns),
        "super" => {
            let depth = segs.iter().take_while(|s| s.as_str() == "super").count();
            env.lookup_super_path(depth, &segs[depth..], ns)
        }
        "self" => env.lookup_self_path(&segs[1..], ns),
        _ => env
            .lookup_self_path(segs, ns)
            .or_else(|| env.lookup_crate_path(segs, ns)),
    }
}

fn path_root_is(node: tree_sitter::Node<'_>, src: &[u8], lang: &dyn Lang, want: &str) -> bool {
    if lang.name() != "rust" {
        return false;
    }
    let Some(root) = scoped_path_root(node) else {
        return false;
    };
    if root.id() == node.id() {
        return false;
    }
    let name = std::str::from_utf8(&src[root.start_byte()..root.end_byte()]).unwrap_or("");
    name == want
}

fn scoped_path_root(mut node: tree_sitter::Node<'_>) -> Option<tree_sitter::Node<'_>> {
    let mut saw_scoped = false;
    while let Some(parent) = node.parent() {
        match parent.kind() {
            "scoped_identifier" | "scoped_type_identifier" => {
                saw_scoped = true;
                node = parent;
            }
            // `use crate::a::f` / `use crate::a::g as gg`: stop at the wrapper so
            // the root stays `crate`, not the whole use line (which looks foreign).
            _ => break,
        }
    }
    if !saw_scoped {
        return None;
    }
    loop {
        match node.kind() {
            "scoped_identifier" | "scoped_type_identifier" => {
                node = node.child_by_field_name("path")?;
            }
            "bracketed_type" => {
                node = node.named_child(0)?;
            }
            "qualified_type" => {
                node = node.child_by_field_name("type")?;
            }
            "generic_type" => {
                node = node.child_by_field_name("type")?;
            }
            _ => return Some(node),
        }
    }
}

fn node_is_wildcard(node: tree_sitter::Node<'_>) -> bool {
    matches!(node.kind(), "_" | "remaining_field_pattern")
}

/// Nested `function`/`class`/`impl` items are separate entities. JS
/// `variable_declarator` is an entity kind at module scope only; inside a
/// function it is a local and must not be a resolver barrier.
fn skip_nested_item(node: tree_sitter::Node<'_>, lang: &dyn Lang, root_id: usize) -> bool {
    if node.id() == root_id {
        return false;
    }
    if node.kind() == "variable_declarator" {
        return false;
    }
    lang.entity_kinds()
        .iter()
        .any(|r| r.node_kind == node.kind())
}

fn is_opaque_node(node: tree_sitter::Node<'_>, lang: &dyn Lang) -> bool {
    lang.opaque_nodes().iter().any(|k| *k == node.kind())
}

fn binder_class(node: tree_sitter::Node<'_>) -> BinderClass {
    match node.kind() {
        "type_parameter" | "lifetime_parameter" | "const_parameter" => BinderClass::Generic,
        "lifetime"
            if node
                .parent()
                .is_some_and(|p| p.kind() == "for_lifetimes") =>
        {
            BinderClass::Generic
        }
        "label" | "statement_identifier" => BinderClass::Label,
        _ => BinderClass::Local,
    }
}

/// Array lengths and const generic args cannot capture ordinary locals or
/// labels (SPEC; rustc E0435). Generic lifetimes are also out of a const
/// *value* (`{ 'a }` / array length) but still bind in a type arg (`Vec<&'a T>`).
fn const_context_hides_binder(node: tree_sitter::Node<'_>, binder: &BinderInfo) -> bool {
    match binder.class {
        BinderClass::Local | BinderClass::Label => in_const_value_position(node),
        BinderClass::Generic if binder.namespace == Namespace::Lifetime => {
            in_const_lifetime_position(node)
        }
        _ => false,
    }
}

/// `g::<n>()` parses `n` as a type_identifier. When that is not a type, it is
/// a const generic argument: a const-generic binder or a Value entity, never
/// an ordinary local (SPEC / rustc E0435).
fn const_generic_arg_ref(
    node: tree_sitter::Node<'_>,
    name: &str,
    range: ByteRange,
    binders: &[BinderInfo],
    env: &Env,
    src: &[u8],
    lang: &dyn Lang,
    root_id: usize,
) -> Option<IdentRef> {
    if node.kind() != "type_identifier" || !in_type_arguments(node) {
        return None;
    }
    let local = binders
        .iter()
        .filter(|b| {
            b.name == name
                && b.namespace == Namespace::Value
                && b.class == BinderClass::Generic
                && b.visible_from <= range.start
                && b.scope.start <= range.start
                && range.end <= b.scope.end
                && !blocked_by_barrier(node, b, Namespace::Value, src, lang, root_id)
        })
        .max_by_key(|b| (b.scope.start, b.range.start));
    if let Some(binder) = local {
        return Some(IdentRef::Local(binder.slot, Namespace::Value));
    }
    env.lookup(name, Namespace::Value).map(IdentRef::Entity)
}

fn in_array_length(node: tree_sitter::Node<'_>) -> bool {
    let mut current = node;
    while let Some(parent) = current.parent() {
        if matches!(parent.kind(), "array_type" | "array_expression") {
            if parent.child_by_field_name("length").is_some_and(|n| {
                n.start_byte() <= node.start_byte() && node.end_byte() <= n.end_byte()
            }) {
                return true;
            }
        }
        current = parent;
    }
    false
}

fn in_type_arguments(node: tree_sitter::Node<'_>) -> bool {
    let mut current = node;
    while let Some(parent) = current.parent() {
        if parent.kind() == "type_arguments" {
            return true;
        }
        current = parent;
    }
    false
}

fn in_const_value_position(node: tree_sitter::Node<'_>) -> bool {
    in_array_length(node) || in_type_arguments(node)
}

fn in_const_lifetime_position(node: tree_sitter::Node<'_>) -> bool {
    if in_array_length(node) {
        return true;
    }
    let mut current = node;
    while let Some(parent) = current.parent() {
        if parent.kind() == "type_arguments" && matches!(current.kind(), "block" | "const_block") {
            return true;
        }
        current = parent;
    }
    false
}

/// Method name of `self.foo()`, `Self::foo()`, `S::foo()` inside `impl S`, or JS
/// `self.foo()` / `Self::foo` / `Self::N` / `this.foo()` — bound to a sibling
/// under the enclosing impl/class, not the flat Value env (a free `fn foo` is
/// a different target). `x.foo()` stays Free: that needs types.
fn is_inherent_method_ref(node: tree_sitter::Node<'_>, src: &[u8]) -> bool {
    match node.kind() {
        "field_identifier" => rust_self_field_call(node),
        "property_identifier" => js_this_member_call(node),
        "identifier" => rust_self_path_method(node, src),
        _ => false,
    }
}

fn rust_self_field_call(node: tree_sitter::Node<'_>) -> bool {
    let Some(parent) = node.parent().filter(|p| p.kind() == "field_expression") else {
        return false;
    };
    if parent.child_by_field_name("field").map(|n| n.id()) != Some(node.id()) {
        return false;
    }
    let Some(value) = parent.child_by_field_name("value") else {
        return false;
    };
    if value.kind() != "self" {
        return false;
    }
    let Some(grand) = parent.parent() else {
        return false;
    };
    grand.kind() == "call_expression"
        && grand.child_by_field_name("function").map(|n| n.id()) == Some(parent.id())
}

fn js_this_member_call(node: tree_sitter::Node<'_>) -> bool {
    let Some(parent) = node.parent().filter(|p| p.kind() == "member_expression") else {
        return false;
    };
    if parent.child_by_field_name("property").map(|n| n.id()) != Some(node.id()) {
        return false;
    }
    let Some(object) = parent.child_by_field_name("object") else {
        return false;
    };
    if object.kind() != "this" {
        return false;
    }
    let Some(grand) = parent.parent() else {
        return false;
    };
    grand.kind() == "call_expression"
        && grand.child_by_field_name("function").map(|n| n.id()) == Some(parent.id())
}

fn prev_token(mut node: tree_sitter::Node<'_>) -> Option<tree_sitter::Node<'_>> {
    loop {
        node = node.prev_sibling()?;
        if node.is_extra() {
            continue;
        }
        return Some(node);
    }
}

fn next_token(mut node: tree_sitter::Node<'_>) -> Option<tree_sitter::Node<'_>> {
    loop {
        node = node.next_sibling()?;
        if node.is_extra() {
            continue;
        }
        return Some(node);
    }
}

fn node_bytes<'a>(node: tree_sitter::Node<'_>, src: &'a [u8]) -> Option<&'a [u8]> {
    let start = node.start_byte();
    let end = node.end_byte();
    (end <= src.len() && start < end).then(|| &src[start..end])
}

/// Soup `impl S { Self::parse() }` has no `scoped_identifier` — just tokens.
fn soup_self_path_method(node: tree_sitter::Node<'_>, src: &[u8]) -> bool {
    let Some(parent) = node.parent() else {
        return false;
    };
    if !matches!(parent.kind(), "token_tree" | "ERROR") {
        return false;
    }
    let Some(colon1) = prev_token(node) else {
        return false;
    };
    let qual = if colon1.kind() == "::" {
        prev_token(colon1)
    } else if colon1.kind() == ":" {
        let Some(colon0) = prev_token(colon1) else {
            return false;
        };
        if colon0.kind() != ":" {
            return false;
        }
        prev_token(colon0)
    } else {
        return false;
    };
    let Some(qual) = qual else {
        return false;
    };
    if qual.kind() == ">" {
        return soup_ufcs_is_enclosing(qual, node, src);
    }
    if !matches!(qual.kind(), "identifier" | "type_identifier" | "self") {
        return false;
    }
    let Some(qt) = node_bytes(qual, src) else {
        return false;
    };
    // `self::parse` is a module path, not `Self::parse`.
    if qt == b"self" {
        return false;
    }
    qt == b"Self"
        || Some(qt) == enclosing_impl_type_name(node, src)
        || Some(qt) == enclosing_impl_trait_name(node, src)
        || Some(qt) == soup_enclosing_impl_type_name(node, src)
        || Some(qt) == soup_enclosing_impl_trait_name(node, src)
}

/// Soup `<S as Tr>::parse` — tokens, not `qualified_type`.
fn soup_ufcs_is_enclosing(
    gt: tree_sitter::Node<'_>,
    node: tree_sitter::Node<'_>,
    src: &[u8],
) -> bool {
    let Some((ty, tr)) = soup_ufcs_parts(gt, src) else {
        return false;
    };
    let enc_ty = enclosing_impl_type_name(node, src).or_else(|| soup_enclosing_impl_type_name(node, src));
    let enc_tr = enclosing_impl_trait_name(node, src).or_else(|| soup_enclosing_impl_trait_name(node, src));
    Some(ty) == enc_ty && Some(tr) == enc_tr
}

fn soup_ufcs_parts<'a>(
    gt: tree_sitter::Node<'a>,
    src: &'a [u8],
) -> Option<(&'a [u8], &'a [u8])> {
    let mut nodes = Vec::new();
    let mut n = prev_token(gt);
    let mut saw_lt = false;
    while let Some(p) = n {
        if p.kind() == "<" {
            saw_lt = true;
            break;
        }
        nodes.push(p);
        n = prev_token(p);
    }
    if !saw_lt {
        return None;
    }
    nodes.reverse();
    let mut depth = 0i32;
    let mut idents: Vec<&'a [u8]> = Vec::new();
    let mut saw_as = false;
    for p in nodes {
        match p.kind() {
            "<" | "type_arguments" | "type_parameters" => depth += 1,
            ">" => depth = depth.saturating_sub(1),
            "as" if depth == 0 => saw_as = true,
            "identifier" | "type_identifier" if depth == 0 => {
                if let Some(t) = node_bytes(p, src) {
                    idents.push(t);
                }
            }
            _ => {}
        }
    }
    if !saw_as || idents.len() < 2 {
        return None;
    }
    Some((idents[0], idents[idents.len() - 1]))
}

/// Soup `self.parse()` — `.` plus identifier, not `field_expression`.
/// The `()` args are a nested `token_tree`, not a `(` sibling.
fn soup_self_field_call(node: tree_sitter::Node<'_>, src: &[u8]) -> bool {
    let Some(parent) = node.parent() else {
        return false;
    };
    if !matches!(parent.kind(), "token_tree" | "ERROR") {
        return false;
    }
    let Some(dot) = prev_token(node) else {
        return false;
    };
    if dot.kind() != "." {
        return false;
    }
    let Some(recv) = prev_token(dot) else {
        return false;
    };
    if !matches!(recv.kind(), "self" | "identifier") {
        return false;
    }
    if node_bytes(recv, src) != Some(b"self") {
        return false;
    }
    next_token(node).is_some_and(|n| matches!(n.kind(), "(" | "token_tree"))
}

fn soup_impl_header_before<'a>(
    body: tree_sitter::Node<'a>,
    src: &'a [u8],
) -> Option<(Option<&'a [u8]>, Option<&'a [u8]>)> {
    let mut nodes = Vec::new();
    let mut saw_impl = false;
    let mut n = body.prev_sibling();
    while let Some(p) = n {
        if p.is_extra() {
            n = p.prev_sibling();
            continue;
        }
        if matches!(p.kind(), "fn" | "mod" | "struct" | "enum" | "trait" | "union") {
            break;
        }
        nodes.push(p);
        if p.kind() == "impl" {
            saw_impl = true;
            break;
        }
        n = p.prev_sibling();
    }
    if !saw_impl {
        return None;
    }
    nodes.reverse();
    let mut idents: Vec<&'a [u8]> = Vec::new();
    let mut saw_for = false;
    let mut depth = 0i32;
    for p in nodes.iter().skip(1) {
        match p.kind() {
            "<" | "type_parameters" | "type_arguments" => depth += 1,
            ">" => depth = depth.saturating_sub(1),
            "for" if depth == 0 => saw_for = true,
            "identifier" | "type_identifier" if depth == 0 => {
                if let Some(t) = node_bytes(*p, src) {
                    idents.push(t);
                }
            }
            _ => {}
        }
    }
    if idents.is_empty() {
        return None;
    }
    if saw_for && idents.len() >= 2 {
        Some((Some(idents[idents.len() - 1]), Some(idents[idents.len() - 2])))
    } else {
        Some((Some(idents[idents.len() - 1]), None))
    }
}

fn soup_enclosing_impl_type_name<'a>(
    mut node: tree_sitter::Node<'a>,
    src: &'a [u8],
) -> Option<&'a [u8]> {
    loop {
        if node.kind() == "token_tree" {
            if let Some((ty, _)) = soup_impl_header_before(node, src) {
                return ty;
            }
        }
        node = node.parent()?;
    }
}

fn soup_enclosing_impl_trait_name<'a>(
    mut node: tree_sitter::Node<'a>,
    src: &'a [u8],
) -> Option<&'a [u8]> {
    loop {
        if node.kind() == "token_tree" {
            if let Some((_, tr)) = soup_impl_header_before(node, src) {
                return tr;
            }
        }
        node = node.parent()?;
    }
}

fn rust_self_path_method(node: tree_sitter::Node<'_>, src: &[u8]) -> bool {
    if soup_self_path_method(node, src) || soup_self_field_call(node, src) {
        return true;
    }
    let Some(parent) = node.parent().filter(|p| p.kind() == "scoped_identifier") else {
        return false;
    };
    if parent.child_by_field_name("name").map(|n| n.id()) != Some(node.id()) {
        return false;
    }
    let Some(path) = parent.child_by_field_name("path") else {
        return false;
    };
    let Some(qual) = scoped_qualifier(path) else {
        return false;
    };
    let start = qual.start_byte();
    let end = qual.end_byte();
    if end > src.len() || start >= end {
        return false;
    }
    let path_text = &src[start..end];
    if path_text != b"Self"
        && Some(path_text) != enclosing_impl_type_name(node, src)
        && Some(path_text) != enclosing_impl_trait_name(node, src)
    {
        return false;
    }
    true
}

/// The `Self` type of the enclosing `impl` (`S` in `impl S` / `impl Trait for S` /
/// `impl<T> S<T>`), or the enclosing trait name (`T` in `trait T`). Used so
/// `S::foo()` / `T::Item` bind like `Self::foo()` / `Self::Item`.
fn enclosing_impl_type_name<'a>(
    mut node: tree_sitter::Node<'a>,
    src: &'a [u8],
) -> Option<&'a [u8]> {
    loop {
        let Some(parent) = node.parent() else {
            return None;
        };
        if parent.kind() == "impl_item" {
            return parent
                .child_by_field_name("type")
                .and_then(|ty| impl_type_base_name(ty, src));
        }
        if parent.kind() == "trait_item" {
            return parent
                .child_by_field_name("name")
                .and_then(|n| impl_type_base_name(n, src));
        }
        node = parent;
    }
}

/// The trait in `impl Trait for S`, so `Tr::Item` / `Tr::foo` inside that impl
/// bind like `Self::Item` / `Self::foo`.
fn enclosing_impl_trait_name<'a>(
    mut node: tree_sitter::Node<'a>,
    src: &'a [u8],
) -> Option<&'a [u8]> {
    loop {
        let Some(parent) = node.parent() else {
            return None;
        };
        if parent.kind() == "impl_item" {
            return parent
                .child_by_field_name("trait")
                .and_then(|ty| impl_type_base_name(ty, src));
        }
        node = parent;
    }
}

fn impl_type_base_name<'a>(ty: tree_sitter::Node<'a>, src: &'a [u8]) -> Option<&'a [u8]> {
    match ty.kind() {
        "type_identifier" | "identifier" => {
            let start = ty.start_byte();
            let end = ty.end_byte();
            (end <= src.len() && start < end).then(|| &src[start..end])
        }
        "generic_type" => ty
            .child_by_field_name("type")
            .and_then(|inner| impl_type_base_name(inner, src)),
        "scoped_type_identifier" => ty
            .child_by_field_name("name")
            .and_then(|inner| impl_type_base_name(inner, src)),
        _ => None,
    }
}

fn is_doc_attribute(node: tree_sitter::Node<'_>, src: &[u8]) -> bool {
    let Some(attr) = node.named_child(0).filter(|n| n.kind() == "attribute") else {
        return false;
    };
    let Some(path) = attr.named_child(0) else {
        return false;
    };
    &src[path.start_byte()..path.end_byte()] == b"doc"
}

fn is_ident_leaf(node: tree_sitter::Node<'_>) -> bool {
    matches!(
        node.kind(),
        "identifier"
            | "type_identifier"
            | "primitive_type"
            | "self"
            | "super"
            | "crate"
            | "lifetime"
            | "label"
            | "statement_identifier"
            | "shorthand_field_identifier"
            | "shorthand_property_identifier"
            | "shorthand_property_identifier_pattern"
    )
}

fn walk(
    node: tree_sitter::Node<'_>,
    item: tree_sitter::Node<'_>,
    src: &[u8],
    lang: &dyn Lang,
    children: &[(ByteRange, EntityId)],
    res: &Resolution,
    binders: &HashMap<(u32, u32), (Slot, Namespace)>,
    tokens: &mut Vec<Token>,
) {
    if node.id() != item.id() {
        if let Some(id) = child_id(node, children) {
            tokens.push(Token::Child(id));
            return;
        }
    }
    if matches!(node.kind(), "attribute_item" | "inner_attribute_item") {
        if !is_doc_attribute(node, src) {
            let r = byte_range(node);
            let text = String::from_utf8_lossy(&src[r.start as usize..r.end as usize]);
            if !text.trim().is_empty() {
                tokens.push(Token::Lit(text.as_ref().into()));
            }
        }
        return;
    }
    if lang.trivia_kinds().iter().any(|k| *k == node.kind()) {
        return;
    }
    if is_opaque_node(node, lang) && node.id() != item.id() {
        let r = byte_range(node);
        let text = String::from_utf8_lossy(&src[r.start as usize..r.end as usize]);
        if !text.trim().is_empty() {
            tokens.push(Token::Lit(text.as_ref().into()));
        }
        return;
    }
    if node.child_count() == 0 {
        if let Some(tok) = leaf_token(node, src, item, lang, res, binders) {
            tokens.push(tok);
        }
        return;
    }
    let mut c = node.walk();
    if c.goto_first_child() {
        loop {
            walk(c.node(), item, src, lang, children, res, binders, tokens);
            if !c.goto_next_sibling() {
                break;
            }
        }
    }
}

fn child_id(node: tree_sitter::Node<'_>, children: &[(ByteRange, EntityId)]) -> Option<EntityId> {
    let start = node.start_byte() as u32;
    let end = node.end_byte() as u32;
    children
        .iter()
        .find(|(r, _)| r.end == end && start >= r.start && start <= r.end)
        .map(|(_, id)| *id)
}

fn leaf_token(
    node: tree_sitter::Node<'_>,
    src: &[u8],
    item: tree_sitter::Node<'_>,
    lang: &dyn Lang,
    res: &Resolution,
    binders: &HashMap<(u32, u32), (Slot, Namespace)>,
) -> Option<Token> {
    let r = byte_range(node);
    let text = String::from_utf8_lossy(&src[r.start as usize..r.end as usize]);
    if text.trim().is_empty() {
        return None;
    }
    if let Some((slot, ns)) = binders.get(&(r.start, r.end)) {
        return Some(Token::Binder(*slot, *ns));
    }
    if let Some(name) = item.child_by_field_name("name") {
        if byte_range(name) == r {
            return Some(Token::Ident(IdentRef::Entity(EntityId::SELF)));
        }
    }
    for (rr, ident) in &res.refs {
        if *rr == r {
            return Some(Token::Ident(ident.clone()));
        }
    }
    if is_ident_leaf(node)
        || matches!(
            node.kind(),
            "field_identifier" | "property_identifier" | "property_identifier_pattern"
        )
    {
        return Some(Token::Ident(IdentRef::Free(text.as_ref().into())));
    }
    let kind = node.kind();
    if lang.literal_kinds().contains(&kind) {
        Some(Token::Lit(text.as_ref().into()))
    } else if kind.chars().all(|c| c.is_ascii_alphabetic() || c == '_') {
        Some(Token::Kw(text.as_ref().into()))
    } else {
        Some(Token::Punct(text.as_ref().into()))
    }
}

crates/svc-core/src/lang.rs.Text:
use std::collections::{HashMap, HashSet};
use std::sync::Arc;

use crate::content::Namespace;
use crate::entity::Kind;
use crate::ids::{ByteRange, EntityId, RelPath};

#[derive(Clone, Debug, Default)]
pub struct Env {
    pub names: Arc<HashMap<(String, Namespace), EntityId>>,
    /// File-root and nested defs keyed by the file they live in. A same-file
    /// `fn hex32` beats a same-named item in another crate when resolving.
    pub by_file: Arc<HashMap<RelPath, HashMap<(String, Namespace), EntityId>>>,
    /// Same-named items in `crates/<pkg>/**` share this map. File wins, then a
    /// name unique in the crate, then a name unique in the repo; collisions are Free.
    pub by_crate: Arc<HashMap<String, HashMap<(String, Namespace), EntityId>>>,
    /// Crate-level names that appear in more than one file. A third file must not
    /// bind last-wins (DOGFOOD: two file-level items with one name in one crate).
    pub crate_ambiguous: Arc<HashMap<String, HashSet<(String, Namespace)>>>,
    /// Repo-wide names that appear under more than one definition.
    pub names_ambiguous: Arc<HashSet<(String, Namespace)>>,
    /// Occupants that own this (name, ns) as their primary namespace (`fn` in
    /// Value, not `struct` which also sits in Value as a constructor).
    pub primary: Arc<HashSet<(String, Namespace)>>,
    /// Per-crate primary occupants; same rule as [`Self::primary`].
    pub crate_primary: Arc<HashMap<String, HashSet<(String, Namespace)>>>,
    /// Inherent methods and associated consts of the impl/class this item is
    /// being resolved in. `self.foo()` / `Self::foo` / `Self::N` / `this.foo()`
    /// look here, not in `names` (a free `fn foo` is a different target).
    pub self_methods: HashMap<String, EntityId>,
    /// Items nested in the function (or JS function/method) being resolved —
    /// `fn f() { fn g() {} g(); }`. They are not in [`Self::by_file`]: a sibling
    /// `fn h() { g(); }` must not bind to `f`'s helper, and a nested `fn parse`
    /// must not make a file-level `parse` in the same crate look ambiguous.
    pub nested_items: HashMap<(String, Namespace), EntityId>,
    /// When set, [`Self::lookup`] prefers [`Self::by_file`] for this path.
    pub current_file: Option<RelPath>,
    /// Inside `mod inner { … }`, bare names are the module's own items only.
    /// `crate::` still uses [`Self::lookup_module`].
    pub in_nested_mod: bool,
    /// Parent-mod maps for `super::` / `super::super::` / … Index 0 is one
    /// `super` (the parent of the enclosing mod). Past the last nested mod,
    /// [`Self::lookup_super`] falls through to [`Self::lookup_module`].
    pub super_stack: Vec<HashMap<(String, Namespace), EntityId>>,
    /// Children of each `mod` entity, for `crate::outer::parse` / `super::inner::f`.
    pub mod_items: HashMap<EntityId, HashMap<(String, Namespace), EntityId>>,
    /// Enclosing `mod` entity, for `self::inner::f`.
    pub self_mod: Option<EntityId>,
    /// File loaded by `mod foo;` → that `mod` entity. Items in the file are
    /// inside the module, not the crate root.
    pub file_of_mod: HashMap<RelPath, EntityId>,
    /// Declaring file of a `mod foo;` entity (`src/lib.rs` for `mod outer;`).
    pub mod_decl_file: HashMap<EntityId, RelPath>,
    /// Parent `mod` of a nested `mod` (`outer` for `mod outer { mod inner; }`).
    pub mod_parent: HashMap<EntityId, EntityId>,
    /// Parent files for `super::` / `super::super::` out of a file module.
    pub super_files: Vec<RelPath>,
    /// Inside an inline `mod inner { }` (not only a file loaded by `mod foo;`).
    pub inline_mod: bool,
    /// Names brought in by `use` in this module. File-module isolation drops
    /// unique-crate lookup, so `use super::parse; parse()` must still bind.
    pub use_imports: HashMap<(String, Namespace), EntityId>,
    /// `use path::h as hh` — `hh` is a local spelling, not an Entity hole.
    pub use_aliases: HashSet<String>,
    /// `pub use` names visible as `crate::parse` / `crate::engine::foo`.
    pub file_reexports: HashMap<RelPath, HashMap<(String, Namespace), EntityId>>,
    /// File-level `use` / `use as` names, including private ones, so
    /// `super::foo::parse` after `use a as foo` in the parent file still binds.
    pub file_imports: HashMap<RelPath, HashMap<(String, Namespace), EntityId>>,
    /// `pub use` inside a `mod`, for `crate::engine::foo` after `pub use merge::foo`.
    pub mod_reexports: HashMap<EntityId, HashMap<(String, Namespace), EntityId>>,
    /// Private `use` / `use as` names inside a `mod`, so `super::foo::parse`
    /// after `mod outer { use a as foo; … }` still binds.
    pub mod_imports: HashMap<EntityId, HashMap<(String, Namespace), EntityId>>,
    /// When set, [`crate::engine::canon`] records pub uses into the reexport maps.
    pub bind_reexports: bool,
    /// Every `mod` entity, so `use a as b; b::parse` is a module path, not Type::name.
    pub mods: HashSet<EntityId>,
    /// `use a as b` / `pub use a as b` — `b` is a local spelling, not the entity's name.
    pub alias_spellings: HashSet<String>,
    /// `#[macro_export]` names. rustc injects them at the crate root, so a
    /// file module's nested-mod isolation still sees `parse!()`.
    pub macro_exports: Arc<HashMap<String, EntityId>>,
    /// Files spliced in by `include!` (`UnownedViaInclude`). `mod bar;` there
    /// loads `bar.rs` next to that file, not `<stem>/bar.rs`.
    pub include_splices: HashSet<RelPath>,
}

impl Env {
    pub fn lookup(&self, name: &str, ns: Namespace) -> Option<EntityId> {
        if let Some(id) = Self::lookup_in_map(Some(&self.nested_items), name, ns) {
            return Some(id);
        }
        if let Some(m) = self.self_mod {
            if let Some(id) = Self::lookup_in_map(self.mod_items.get(&m), name, ns) {
                return Some(id);
            }
        }
        if let Some(id) = Self::lookup_in_map(Some(&self.use_imports), name, ns) {
            return Some(id);
        }
        if self.use_aliases.contains(name) {
            return None;
        }
        if ns == Namespace::Value {
            if let Some(&id) = self.macro_exports.get(name) {
                return Some(id);
            }
        }
        if self.in_nested_mod {
            return None;
        }
        self.lookup_module(name, ns)
    }

    /// `super::f` (`depth` 1) / `super::super::f` (`depth` 2). Past the last
    /// nested parent module, this is the crate root.
    pub fn lookup_super(&self, name: &str, ns: Namespace, depth: usize) -> Option<EntityId> {
        if depth == 0 {
            return None;
        }
        let i = depth - 1;
        if let Some(map) = self.super_stack.get(i) {
            return Self::lookup_in_map(Some(map), name, ns);
        }
        let rest = i - self.super_stack.len();
        if self.inline_mod && rest == 0 {
            return self
                .current_file
                .as_ref()
                .and_then(|file| self.lookup_file(file, name, ns))
                .or_else(|| self.lookup_module(name, ns));
        }
        let file_i = if self.inline_mod { rest - 1 } else { rest };
        if let Some(file) = self.super_files.get(file_i) {
            if let Some(id) = self.lookup_file(file, name, ns) {
                return Some(id);
            }
            // `mod bar;` may live in an include! splice; `super::` is still the
            // parent module, whose items sit on other files of that module.
            if self.include_splices.contains(file) {
                if let Some(&m) = self.file_of_mod.get(file) {
                    if let Some(id) = self.lookup_in_mod(m, name, ns) {
                        return Some(id);
                    }
                }
            }
        }
        self.lookup_module(name, ns)
    }

    /// `crate::a::b` — `a` is crate-root, then each segment is a child of that mod.
    pub fn lookup_crate_path(&self, segs: &[String], ns: Namespace) -> Option<EntityId> {
        if segs.is_empty() {
            return None;
        }
        if segs.len() == 1 {
            return self.lookup_crate_root(&segs[0], ns);
        }
        let start = self.lookup_crate_root(&segs[0], Namespace::Type)?;
        self.walk_mod_path(start, &segs[1..], ns)
    }

    /// `crate::parse` is the crate root, not a same-named item in this file module.
    fn lookup_crate_root(&self, name: &str, ns: Namespace) -> Option<EntityId> {
        if let Some(file) = self.super_files.last() {
            return self.lookup_file(file, name, ns);
        }
        if let Some(file) = &self.current_file {
            if let Some(id) = self.lookup_file(file, name, ns) {
                return Some(id);
            }
        }
        self.lookup_module(name, ns)
    }

    fn lookup_file(&self, file: &RelPath, name: &str, ns: Namespace) -> Option<EntityId> {
        Self::lookup_in_map(self.by_file.get(file), name, ns)
            .or_else(|| Self::lookup_in_map(self.file_reexports.get(file), name, ns))
            .or_else(|| Self::lookup_in_map(self.file_imports.get(file), name, ns))
    }

    /// `super::a::b` after `depth` `super::` prefixes.
    pub fn lookup_super_path(
        &self,
        depth: usize,
        segs: &[String],
        ns: Namespace,
    ) -> Option<EntityId> {
        if segs.is_empty() {
            return None;
        }
        if segs.len() == 1 {
            return self.lookup_super(&segs[0], ns, depth);
        }
        let start = self.lookup_super(&segs[0], Namespace::Type, depth)?;
        self.walk_mod_path(start, &segs[1..], ns)
    }

    /// `self::a::b` in the enclosing module.
    pub fn lookup_self_path(&self, segs: &[String], ns: Namespace) -> Option<EntityId> {
        if segs.is_empty() {
            return None;
        }
        let start_mod = self.self_mod?;
        if segs.len() == 1 {
            return self.lookup_in_mod(start_mod, &segs[0], ns);
        }
        let start = self.lookup_in_mod(start_mod, &segs[0], Namespace::Type)?;
        self.walk_mod_path(start, &segs[1..], ns)
    }

    fn lookup_in_mod(&self, m: EntityId, name: &str, ns: Namespace) -> Option<EntityId> {
        Self::lookup_in_map(self.mod_items.get(&m), name, ns)
            .or_else(|| Self::lookup_in_map(self.mod_reexports.get(&m), name, ns))
            .or_else(|| Self::lookup_in_map(self.mod_imports.get(&m), name, ns))
    }

    fn walk_mod_path(&self, start: EntityId, rest: &[String], ns: Namespace) -> Option<EntityId> {
        if rest.is_empty() {
            return Some(start);
        }
        let mut id = start;
        for s in &rest[..rest.len() - 1] {
            id = self.lookup_in_mod(id, s, Namespace::Type)?;
        }
        self.lookup_in_mod(id, rest.last()?, ns)
    }

    /// `use a as b; b::parse` — `b` names a module, then walk its children.
    /// A `pub use a as b` at the crate root is visible from a file module even
    /// though nested-mod isolation hides it from [`Self::lookup`].
    pub fn lookup_aliased_mod_path(&self, segs: &[String], ns: Namespace) -> Option<EntityId> {
        if segs.len() < 2 {
            return None;
        }
        let start = self
            .lookup(&segs[0], Namespace::Type)
            .or_else(|| self.lookup_crate_path(&segs[..1], Namespace::Type))?;
        if !self.mods.contains(&start) {
            return None;
        }
        self.walk_mod_path(start, &segs[1..], ns)
    }

    pub fn is_mod(&self, id: EntityId) -> bool {
        self.mods.contains(&id)
    }

    /// File / crate / repo names, skipping nested-mod isolation. `crate::f`
    /// inside `mod inner` still binds the crate-root item.
    pub fn lookup_module(&self, name: &str, ns: Namespace) -> Option<EntityId> {
        if let Some(file) = &self.current_file {
            if let Some(id) = Self::lookup_in_map(self.by_file.get(file), name, ns) {
                return Some(id);
            }
            if let Some(krate) = crate_key(file) {
                if !self
                    .crate_ambiguous
                    .get(krate)
                    .is_some_and(|s| Self::is_ambiguous(s, name, ns))
                {
                    if let Some(id) = Self::lookup_in_map(self.by_crate.get(krate), name, ns) {
                        return Some(id);
                    }
                }
            }
        }
        self.lookup_global(name, ns)
    }

    pub fn lookup_global(&self, name: &str, ns: Namespace) -> Option<EntityId> {
        if Self::is_ambiguous(&self.names_ambiguous, name, ns) {
            return None;
        }
        Self::lookup_in_map(Some(self.names.as_ref()), name, ns)
    }

    fn is_ambiguous(set: &HashSet<(String, Namespace)>, name: &str, ns: Namespace) -> bool {
        set.contains(&(name.to_string(), ns))
            || set.contains(&(name.to_string(), Namespace::Any))
    }

    fn lookup_in_map(
        map: Option<&HashMap<(String, Namespace), EntityId>>,
        name: &str,
        ns: Namespace,
    ) -> Option<EntityId> {
        let map = map?;
        map.get(&(name.to_string(), ns))
            .copied()
            .or_else(|| map.get(&(name.to_string(), Namespace::Any)).copied())
    }

    pub fn insert(&mut self, name: impl Into<String>, ns: Namespace, id: EntityId) {
        self.insert_ranked(name, ns, id, false);
    }

    fn insert_ranked(
        &mut self,
        name: impl Into<String>,
        ns: Namespace,
        id: EntityId,
        primary: bool,
    ) {
        let name = name.into();
        Self::occupy(
            Arc::make_mut(&mut self.names),
            Arc::make_mut(&mut self.names_ambiguous),
            Arc::make_mut(&mut self.primary),
            &name,
            ns,
            id,
            primary,
        );
    }

    /// Two primaries (`fn parse` in two files) or two secondaries are
    /// ambiguous. A primary may replace a secondary (`fn Foo` after
    /// `struct Foo`) without last-wins Free — they share a spelling, not a
    /// namespace.
    fn occupy(
        map: &mut HashMap<(String, Namespace), EntityId>,
        amb: &mut HashSet<(String, Namespace)>,
        primaries: &mut HashSet<(String, Namespace)>,
        name: &str,
        ns: Namespace,
        id: EntityId,
        primary: bool,
    ) {
        let key = (name.to_string(), ns);
        if let Some(old) = map.get(&key) {
            if *old != id {
                let old_primary = primaries.contains(&key);
                if old_primary && !primary {
                    return;
                }
                if old_primary == primary {
                    amb.insert(key.clone());
                }
            }
        }
        map.insert(key.clone(), id);
        if primary {
            primaries.insert(key);
        }
    }

    pub fn export_macro(&mut self, name: impl Into<String>, id: EntityId) {
        Arc::make_mut(&mut self.macro_exports).insert(name.into(), id);
    }

    pub fn insert_def(&mut self, name: impl Into<String>, kind: Kind, id: EntityId) {
        self.insert_def_in(name, kind, id, None);
    }

    pub fn insert_def_in(
        &mut self,
        name: impl Into<String>,
        kind: Kind,
        id: EntityId,
        file: Option<&RelPath>,
    ) {
        let name = name.into();
        if kind == Kind::Mod {
            self.mods.insert(id);
        }
        for ns in namespaces_for(kind) {
            if *ns == Namespace::Value
                && !is_value_primary(kind)
                && self.lookup_global(&name, Namespace::Value).is_some()
            {
                continue;
            }
            let primary = is_value_primary(kind) && *ns == Namespace::Value;
            self.insert_ranked(&name, *ns, id, primary);
            if let Some(file) = file {
                Arc::make_mut(&mut self.by_file)
                    .entry(file.clone())
                    .or_default()
                    .insert((name.clone(), *ns), id);
                if let Some(krate) = crate_key(file) {
                    self.insert_crate(krate, &name, *ns, id, primary);
                }
            }
        }
        if is_value_primary(kind) {
            self.insert_ranked(&name, Namespace::Value, id, true);
            if let Some(file) = file {
                Arc::make_mut(&mut self.by_file)
                    .entry(file.clone())
                    .or_default()
                    .insert((name.clone(), Namespace::Value), id);
                if let Some(krate) = crate_key(file) {
                    self.insert_crate(krate, &name, Namespace::Value, id, true);
                }
            }
        }
    }

    fn insert_crate(
        &mut self,
        krate: &str,
        name: &str,
        ns: Namespace,
        id: EntityId,
        primary: bool,
    ) {
        Self::occupy(
            Arc::make_mut(&mut self.by_crate)
                .entry(krate.to_string())
                .or_default(),
            Arc::make_mut(&mut self.crate_ambiguous)
                .entry(krate.to_string())
                .or_default(),
            Arc::make_mut(&mut self.crate_primary)
                .entry(krate.to_string())
                .or_default(),
            name,
            ns,
            id,
            primary,
        );
    }

    pub fn insert_defs(&mut self, defs: &[(&str, Kind, EntityId)]) {
        for (name, kind, id) in defs {
            self.insert_def(*name, *kind, *id);
        }
    }

    /// Bind a nested item for the duration of one `resolve`. Last insert wins
    /// so an inner function's helper shadows one on an enclosing function.
    pub fn insert_nested(&mut self, name: impl Into<String>, kind: Kind, id: EntityId) {
        let name = name.into();
        for ns in namespaces_for(kind) {
            self.nested_items.insert((name.clone(), *ns), id);
        }
    }

    pub fn insert_mod_child(
        &mut self,
        parent: EntityId,
        name: impl Into<String>,
        kind: Kind,
        id: EntityId,
    ) {
        self.mods.insert(parent);
        if kind == Kind::Mod {
            self.mods.insert(id);
            self.mod_parent.insert(id, parent);
        }
        let map = self.mod_items.entry(parent).or_default();
        Self::insert_super_level(map, name, kind, id);
    }

    pub fn insert_super_level(
        map: &mut HashMap<(String, Namespace), EntityId>,
        name: impl Into<String>,
        kind: Kind,
        id: EntityId,
    ) {
        let name = name.into();
        for ns in namespaces_for(kind) {
            map.insert((name.clone(), *ns), id);
        }
    }
}

pub fn namespaces_for(kind: Kind) -> &'static [Namespace] {
    match kind {
        Kind::Fn | Kind::Const | Kind::Static | Kind::Macro => &[Namespace::Value],
        Kind::Struct | Kind::Enum => &[Namespace::Type, Namespace::Value],
        Kind::Union | Kind::Trait | Kind::TypeAlias => &[Namespace::Type],
        Kind::Mod => &[Namespace::Value, Namespace::Type],
        Kind::Impl | Kind::Opaque | Kind::JsStaticBlock => &[],
        Kind::JsFunction
        | Kind::JsClass
        | Kind::JsMethod
        | Kind::JsGetter
        | Kind::JsSetter
        | Kind::JsField
        | Kind::JsStaticMethod
        | Kind::JsStaticField
        | Kind::JsDeclarator => &[Namespace::Value],
    }
}

fn is_value_primary(kind: Kind) -> bool {
    matches!(
        kind,
        Kind::Fn
            | Kind::Const
            | Kind::Static
            | Kind::Macro
            | Kind::JsFunction
            | Kind::JsClass
            | Kind::JsMethod
            | Kind::JsGetter
            | Kind::JsSetter
            | Kind::JsField
            | Kind::JsStaticMethod
            | Kind::JsStaticField
            | Kind::JsDeclarator
    )
}

/// `crates/svc-core/src/ids.rs` → `svc-core`. Paths outside `crates/` have no crate key.
fn crate_key(file: &RelPath) -> Option<&str> {
    file.as_str()
        .strip_prefix("crates/")
        .and_then(|rest| rest.split('/').next())
        .filter(|s| !s.is_empty())
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub struct EntityKindRule {
    pub node_kind: &'static str,
    pub kind: Kind,
    pub name_field: Option<&'static str>,
    pub body_field: Option<&'static str>,
    pub children_field: Option<&'static str>,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Locator {
    Itself,
    Field(&'static str),
    ChildIndex(usize),
    FieldWithKind(&'static str, &'static str),
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Visibility {
    Whole,
    AfterStmt,
    /// Fields resolve against the binder's own parent, not the scope node.
    Sub(&'static [&'static str]),
    Hoisted,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum BinderClass {
    Local,
    Generic,
    Label,
    Item,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum When {
    Always,
    ThroughBlock,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub struct Barrier {
    pub ns: Namespace,
    pub class: BinderClass,
    pub when: When,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Role {
    Binder {
        namespace: Namespace,
        visibility: Visibility,
        locator: Locator,
    },
    Reference {
        namespace: Namespace,
    },
    Scope {
        opens: &'static [Namespace],
        barriers: &'static [Barrier],
    },
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub struct CommutativeRule {
    pub parent: Option<Kind>,
    pub only_child_kinds: Option<&'static [Kind]>,
    pub except_child_kinds: Option<&'static [Kind]>,
}

pub trait Lang: Send + Sync {
    fn language(&self) -> tree_sitter::Language;
    fn name(&self) -> &'static str;
    fn extensions(&self) -> &'static [&'static str];
    fn entity_kinds(&self) -> &'static [EntityKindRule];
    fn entity_name(&self, node: tree_sitter::Node<'_>, src: &[u8]) -> Option<String>;
    fn roles(
        &self,
        node: tree_sitter::Node<'_>,
        field: Option<&str>,
        src: &[u8],
        env: &Env,
    ) -> Vec<Role>;
    fn opaque_nodes(&self) -> &'static [&'static str];
    fn commutative_parents(&self) -> &'static [CommutativeRule];
    fn trivia_kinds(&self) -> &'static [&'static str];
    /// Text to wrap a lone member in so it parses, when a definition is added to or edited
    /// under a parent of `parent` kind: a JS method is not a program on its own, a Rust
    /// impl method is an item. `None` means the member parses standalone.
    fn member_shell(&self, _parent: Kind) -> Option<(&'static str, &'static str)> {
        None
    }

    /// Leaf node kinds whose text is a literal (numbers, strings, chars, booleans);
    /// canonicalisation keeps their text as `Token::Lit`.
    fn literal_kinds(&self) -> &'static [&'static str] {
        &[]
    }
    /// Override the table kind for nodes that share a grammar kind (JS getters/setters).
    fn refine_kind(&self, _node: tree_sitter::Node<'_>, _src: &[u8]) -> Option<Kind> {
        None
    }
}

pub struct Langs {
    langs: Vec<Box<dyn Lang>>,
}

impl Langs {
    pub fn new(langs: Vec<Box<dyn Lang>>) -> Self {
        Self { langs }
    }

    pub fn for_path(&self, p: &RelPath) -> Option<&dyn Lang> {
        let ext = p.extension()?;
        self.langs
            .iter()
            .find(|l| l.extensions().iter().any(|e| *e == ext))
            .map(|b| &**b)
    }

    pub fn iter(&self) -> impl Iterator<Item = &dyn Lang> {
        self.langs.iter().map(|b| &**b)
    }
}

#[derive(Clone, Debug)]
pub struct RawEntity {
    pub kind: Kind,
    pub name: String,
    pub name_range: Option<ByteRange>,
    pub item_range: ByteRange,
    pub bytes_range: ByteRange,
    pub parent_idx: Option<usize>,
    pub children: Vec<usize>,
    /// `#[path = "bar.rs"]` on `mod foo;` — the file that is this module.
    pub path_attr: Option<String>,
    /// `#[macro_export]` — rustc puts the macro at the crate root even when
    /// the definition sits in a nested module.
    pub macro_export: bool,
    /// `#[macro_use]` on `mod fs` — rustc injects that module's macros at the
    /// crate root, like `#[macro_export]` on each of them.
    pub macro_use: bool,
    /// `#[macro_use(parse, other)]` — only these names. `None` with `macro_use`
    /// means every macro in the module.
    pub macro_use_only: Option<Vec<String>>,
    /// `include!("foo.rs")` paths inside this `mod`, relative to the declaring file.
    pub include_paths: Vec<String>,
}

#[derive(Clone, Debug, Default)]
pub struct Resolution {
    pub slots: Vec<(ByteRange, crate::ids::Slot, Namespace)>,
    pub refs: Vec<(ByteRange, crate::content::IdentRef)>,
}

crates/svc-core/tests/o3_rename.rs.Text:
use std::collections::BTreeMap;

use svc_core::engine::{
    add_def, edit_def, ingest_file, lookup_name, redefine, rename, render, rust_langs,
    snapshot_files, status_report,
};
use svc_core::ids::{ChangeId, EntityId, RelPath};
use svc_core::store::MemStore;
use svc_core::{IdentRef, Intent, RustLang, Store, Token};

const SRC: &str = r#"fn parse(s: &str) -> usize { s.len() }
fn load(path: &str) -> usize { parse(path) }
"#;

#[test]
fn o3_rename_does_not_touch_other_hashes() {
    let store = MemStore::new();
    let lang = RustLang;
    let path = RelPath::new("src/lib.rs").unwrap();
    let snap = ingest_file(SRC.as_bytes(), path, &lang, &store, ChangeId::new()).unwrap();
    let parse_id = lookup_name(&snap, "parse").unwrap();
    let load_id = lookup_name(&snap, "load").unwrap();
    let load_before = snap.entities[&load_id].clone();
    let parse_before = snap.entities[&parse_id].clone();

    let next = rename(&store, &snap, parse_id, "parse_config").unwrap();
    let load_after = &next.entities[&load_id];
    let parse_after = &next.entities[&parse_id];

    assert_eq!(parse_after.name, "parse_config");
    assert_eq!(parse_after.content, parse_before.content);
    assert_eq!(parse_after.bytes, parse_before.bytes);
    assert_eq!(load_after.content, load_before.content);
    assert_eq!(load_after.bytes, load_before.bytes);

    let langs = rust_langs();
    let rendered = render(&next, &store, &langs, false).unwrap();
    let text = String::from_utf8(rendered.files.values().next().unwrap().clone()).unwrap();
    assert!(text.contains("fn parse_config"), "{text}");
    assert!(text.contains("parse_config(path)"), "{text}");
    assert!(!text.contains("fn parse("), "{text}");
}

#[test]
fn snapshot_files_matches_ingest_and_status_is_clean() {
    let store = MemStore::new();
    let langs = rust_langs();
    let path = RelPath::new("src/lib.rs").unwrap();
    let mut files = BTreeMap::new();
    files.insert(path.clone(), SRC.as_bytes().to_vec());
    let change = ChangeId::new();
    let snap = snapshot_files(&store, &langs, &files, None, change).unwrap();
    assert!(snap.entities.values().any(|e| e.name == "parse"));
    assert!(snap.entities.values().any(|e| e.name == "load"));
    let again = snapshot_files(&store, &langs, &files, Some(&snap), change).unwrap();
    let report = status_report(&store, &snap, &again).unwrap();
    assert_eq!(
        report.summary(),
        format!("{} entities, 0 changes", snap.entities.len())
    );
}

#[test]
fn redefine_keeps_callees_as_entity_holes() {
    let store = MemStore::new();
    let langs = rust_langs();
    let path = RelPath::new("src/lib.rs").unwrap();
    let mut files = BTreeMap::new();
    files.insert(path, SRC.as_bytes().to_vec());
    let snap = snapshot_files(&store, &langs, &files, None, ChangeId::new()).unwrap();
    let load_id = lookup_name(&snap, "load").unwrap();
    let parse_id = lookup_name(&snap, "parse").unwrap();
    let text = b"fn load(path: &str) -> usize { parse(path) + 1 }\n";
    let (_, content, bytes) = redefine(&store, &langs, &snap, load_id, text).unwrap();
    let c = store.get_content(content).unwrap();
    assert!(
        c.tokens.iter().any(|t| match t {
            Token::Ident(IdentRef::Entity(id)) => *id == parse_id,
            _ => false,
        }),
        "callee must resolve to parse's entity id, got {:?}",
        c.tokens
    );
    let _ = bytes;
}

